-- SYNTHETIC DATA ONLY. Import into a new disposable database.
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, full_name TEXT, email TEXT, phone TEXT, date_of_birth TEXT, ssn TEXT, street_address TEXT, city TEXT, country TEXT, synthetic INTEGER);
CREATE TABLE employees (employee_id INTEGER PRIMARY KEY, full_name TEXT, work_email TEXT, ssn TEXT, annual_salary INTEGER, bank_routing_number TEXT, bank_account_number TEXT, performance_rating TEXT, synthetic INTEGER);
CREATE TABLE medical_records (record_id INTEGER PRIMARY KEY, customer_id INTEGER, patient_name TEXT, medical_record_number TEXT, diagnosis TEXT, icd10_code TEXT, medication TEXT, insurance_member_id TEXT, encounter_date TEXT, synthetic INTEGER, FOREIGN KEY (customer_id) REFERENCES customers(customer_id));
CREATE TABLE payment_cards (payment_id INTEGER PRIMARY KEY, customer_id INTEGER, cardholder_name TEXT, card_number TEXT, expiration_month INTEGER, expiration_year INTEGER, billing_email TEXT, transaction_amount DECIMAL(12,2), currency TEXT, synthetic INTEGER, FOREIGN KEY (customer_id) REFERENCES customers(customer_id));
